class Solution {
    vector<int> parent, rank_;

    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    void unite(int x, int y) {
        int rx = find(x), ry = find(y);
        if (rx == ry) return;
        if (rank_[rx] < rank_[ry]) {
            parent[rx] = ry;
        } else if (rank_[rx] > rank_[ry]) {
            parent[ry] = rx;
        } else {
            parent[ry] = rx;
            rank_[rx]++;
        }
    }

public:
    int countCompleteComponents(int n, vector<vector<int>>& edges) {
        parent.resize(n);
        rank_.assign(n, 0);
        for (int i = 0; i < n; i++) parent[i] = i;

        for (auto& e : edges) {
            unite(e[0], e[1]);
        }

        vector<int> nodeCount(n, 0), edgeCount(n, 0);
        for (int i = 0; i < n; i++) {
            nodeCount[find(i)]++;
        }
        for (auto& e : edges) {
            edgeCount[find(e[0])]++;
        }

        int ans = 0;
        for (int i = 0; i < n; i++) {
            if (find(i) == i) {
                int m = nodeCount[i];
                if (edgeCount[i] == m * (m - 1) / 2) {
                    ans++;
                }
            }
        }
        return ans;
    }
};
